def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_nth_prime(n):
    count = 0
    num = 1
    primes = []
    while count < n:
        num += 1
        if is_prime(num):
            count += 1
            primes.append(num)
    return primes[-1]

p67 = find_nth_prime(67)
print(f"The 67th prime number (p_67) is: {p67}")

