def prime_sieve(n):
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False
    return primes

# We need the 67th prime. A rough estimate for the nth prime p_n is n ln(n).
# 67 * ln(67) approx 67 * 4.2 = 281. Let's sieve up to 350 to be safe.
primes = prime_sieve(350)
if len(primes) >= 67:
    p_67 = primes[66] # 0-indexed
    print(f"The 67th prime is: {p_67}")
else:
    print("Sieve limit was too low.")

